package tracebaseline

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"time"
)

// ComparisonReport pairs pipeline-disabled and full SkyWalking runs over one fixture.
type ComparisonReport struct {
	GeneratedAt time.Time   `json:"generatedAt"`
	Baseline    SuiteReport `json:"baseline"`
	SkyWalking  SuiteReport `json:"skywalking"`
}

// RenderComparisonHTML writes the paired Phase 10 performance report.
func RenderComparisonHTML(writer io.Writer, comparison ComparisonReport) error {
	encoded, marshalErr := json.Marshal(comparison)
	if marshalErr != nil {
		return fmt.Errorf("cannot encode trace merge comparison for HTML: %w", marshalErr)
	}
	document := strings.Replace(comparisonHTML, "__COMPARISON_JSON__", string(encoded), 1)
	if _, writeErr := io.WriteString(writer, document); writeErr != nil {
		return fmt.Errorf("cannot write trace merge comparison HTML: %w", writeErr)
	}
	return nil
}

